// Builds the site's generated files from the source data:
//   data/data.json + data/lga.json  ->  site/assets/js/data.js
//   three.js and the fonts (pinned npm packages)  ->  site/assets/vendor, site/assets/fonts
// Run with: npm run build. CI checks that the committed output is up to date.
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import polylabel from 'polylabel';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => JSON.parse(readFileSync(join(root, p), 'utf8'));
const data = read('data/data.json');
const geo = read('data/lga.json');

// Label anchor for each council: the point inside its largest piece that is furthest from
// the edge (the "pole of inaccessibility"), worked out on a locally flat projection.
const COS = Math.cos((33.85 * Math.PI) / 180);
const ringArea = (ring) => {
  let a = 0;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) a += (ring[j][0] - ring[i][0]) * (ring[j][1] + ring[i][1]);
  return Math.abs(a / 2);
};
const features = geo.features.map((f) => {
  const polys = f.geometry.coordinates;
  const largest = polys.reduce((a, b) => (ringArea(b[0]) > ringArea(a[0]) ? b : a));
  const projected = largest.map((ring) => ring.map(([x, y]) => [x * COS, y]));
  const [px, py] = polylabel(projected, 0.0005);
  return {
    name: f.properties.name,
    study: f.properties.study,
    label: [Math.round((px / COS) * 1e4) / 1e4, Math.round(py * 1e4) / 1e4],
    polygons: polys,
  };
});

const names = new Set(data.areas.map((a) => a.name));
const study = features.filter((f) => f.study);
if (study.length !== names.size || !study.every((f) => names.has(f.name))) {
  throw new Error('Council boundaries and data.json disagree on the 13 councils');
}

const out = {
  areas: data.areas,
  sites: data.sites,
  bands: data.bands,
  boundaries: features,
};
const banner =
  '// Generated by scripts/build.mjs from data/data.json and data/lga.json. Do not edit by hand.\n' +
  '// Boundaries: ABS ASGS Edition 3 LGAs (CC BY 4.0), simplified, via the nswgeo package (MIT).\n';
mkdirSync(join(root, 'site/assets/js'), { recursive: true });
writeFileSync(join(root, 'site/assets/js/data.js'), `${banner}export const DATA = ${JSON.stringify(out)};\n`);

// Vendored libraries and fonts, copied from exact pinned versions.
const copies = [
  ['node_modules/three/build/three.module.min.js', 'site/assets/vendor/three.module.min.js'],
  ['node_modules/three/LICENSE', 'site/assets/vendor/three.LICENSE.txt'],
];
const fonts = {
  '@fontsource-variable/inter': ['latin', 'latin-ext', 'vietnamese', 'greek', 'cyrillic'].map((s) => `inter-${s}-wght-normal.woff2`),
  '@fontsource-variable/fraunces': ['latin', 'latin-ext'].map((s) => `fraunces-${s}-wght-normal.woff2`),
  '@fontsource-variable/jetbrains-mono': ['latin'].map((s) => `jetbrains-mono-${s}-wght-normal.woff2`),
};
for (const [pkg, files] of Object.entries(fonts)) {
  for (const f of files) copies.push([`node_modules/${pkg}/files/${f}`, `site/assets/fonts/${f}`]);
  copies.push([`node_modules/${pkg}/LICENSE`, `site/assets/fonts/${pkg.split('/')[1]}.LICENSE.txt`]);
}
for (const [from, to] of copies) {
  mkdirSync(dirname(join(root, to)), { recursive: true });
  copyFileSync(join(root, from), join(root, to));
}
console.log(`Built data.js (${study.length} councils, ${features.length - study.length} neighbours) and copied ${copies.length} files.`);

// ---------- Pages ----------
// Each page in src/pages has a JSON header comment and a body. The shared header and footer are
// added here, and {{tokens}} are replaced with numbers from the model, so the text is right even
// before any script runs and every page quotes the same figures.
const { readdirSync } = await import('node:fs');
const model = await import('../site/assets/js/model.js');
const { AREAS, TOTALS, DEFAULTS, makePlan, fmt, round100 } = model;
const plan = makePlan(DEFAULTS);
const tokens = {
  hidden_total: fmt(Math.round(TOTALS.hidden / 1000) * 1000),
  hidden_exact: fmt(TOTALS.hidden),
  high_total: fmt(round100(TOTALS.high)),
  adults_total: (TOTALS.adults / 1e6).toFixed(2),
  unreported_pct: ((TOTALS.hidden / TOTALS.high) * 100).toFixed(1),
  prevalence_pct: ((TOTALS.high / TOTALS.adults) * 100).toFixed(1),
  plan_n: String(DEFAULTS.stations),
  plan_reach: fmt(round100(plan.plan.reach)),
  naive_reach: fmt(round100(plan.naive.reach)),
  plan_gain_pct: (((plan.plan.reach - plan.naive.reach) / plan.naive.reach) * 100).toFixed(0),
  plan_extra: fmt(round100(plan.plan.reach - plan.naive.reach)),
  venues: String(model.SITES.length),
  councils: String(AREAS.length),
  top_council: [...AREAS].sort((a, b) => b.hidden - a.hidden)[0].name,
  top_rate_council: [...AREAS].sort((a, b) => b.rate - a.rate)[0].name,
};

const NAV = [
  ['index.html', 'Overview'],
  ['planner.html', 'Planner'],
  ['councils.html', 'Councils'],
  ['posters.html', 'Posters'],
  ['method.html', 'Method'],
];
const CSP = "default-src 'self'; script-src 'self'; style-src 'self'; font-src 'self'; img-src 'self' data: blob:; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'";
const LOGO = '<svg viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="16" r="15" fill="var(--red)"/><path d="M5 17h6l2.5-6 4 11 3-8 1.8 3H27" fill="none" stroke="#fff" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const esc = (s) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);

function page(file) {
  const src = readFileSync(join(root, 'src/pages', file), 'utf8');
  const m = src.match(/^<!--meta (\{.*?\}) -->\n/s);
  if (!m) throw new Error(`${file}: missing meta header`);
  const meta = JSON.parse(m[1]);
  let body = src.slice(m[0].length);
  body = body.replace(/\{\{(\w+)\}\}/g, (_, k) => {
    if (!(k in tokens)) throw new Error(`${file}: unknown token ${k}`);
    return esc(tokens[k]);
  });
  const nav = NAV.map(([href, label]) => `<a href="${href}"${href === file ? ' aria-current="page"' : ''}>${label}</a>`).join('');
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta http-equiv="Content-Security-Policy" content="${CSP}">
<meta name="referrer" content="no-referrer">
<meta name="color-scheme" content="light dark">
<title>${esc(meta.title)}</title>
<meta name="description" content="${esc(meta.description)}">
<link rel="icon" href="assets/icon.svg" type="image/svg+xml">
<link rel="preload" href="assets/fonts/inter-latin-wght-normal.woff2" as="font" type="font/woff2" crossorigin>
<link rel="preload" href="assets/fonts/fraunces-latin-wght-normal.woff2" as="font" type="font/woff2" crossorigin>
<link rel="stylesheet" href="assets/css/site.css">
<script src="assets/js/theme.js"></script>
<script type="module" src="assets/js/${meta.script}"></script>
</head>
<body data-page="${file.replace('.html', '')}">
<a class="skip" href="#main">Skip to content</a>
<header class="site-header">
  <div class="bar">
    <a class="brand" href="index.html">${LOGO}<span>HiddenPressure</span></a>
    <button class="icon-btn menu-btn" type="button" aria-expanded="false" aria-controls="site-nav" aria-label="Menu"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></button>
    <nav class="nav" id="site-nav" aria-label="Main">${nav}</nav>
    <button class="icon-btn theme-btn" type="button" aria-label="Switch theme"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3a9 9 0 1 0 9 9 7 7 0 0 1-9-9Z" fill="currentColor"/></svg></button>
  </div>
</header>
<main id="main">
${body.trim()}
</main>
<footer class="site-footer">
  <div class="inner">
    <div>
      <h4>HiddenPressure</h4>
      <p>A planning tool for free blood pressure checks in Western Sydney. It estimates where undiagnosed high blood pressure is likely and where check stations would reach the most people. It's a planning aid, not medical advice.</p>
    </div>
    <div>
      <h4>Pages</h4>
      <ul>${NAV.map(([href, label]) => `<li><a href="${href}">${label}</a></li>`).join('')}</ul>
    </div>
    <div>
      <h4>Data</h4>
      <ul>
        <li>ABS National Health Survey 2022</li>
        <li>ABS Census 2021 and SEIFA 2021</li>
        <li>ABS ASGS 2021 boundaries (CC BY 4.0)</li>
        <li><a href="https://github.com/reihooneh/hiddenpressure">Source code on GitHub</a></li>
      </ul>
    </div>
  </div>
</footer>
</body>
</html>
`;
}
let pages = 0;
for (const file of readdirSync(join(root, 'src/pages')).filter((f) => f.endsWith('.html')).sort()) {
  writeFileSync(join(root, 'site', file), page(file));
  pages++;
}
writeFileSync(join(root, 'site/assets/icon.svg'), LOGO.replace('<svg ', '<svg xmlns="http://www.w3.org/2000/svg" ').replace('var(--red)', '#c4372c').replace(' aria-hidden="true"', '') + '\n');
console.log(`Built ${pages} pages.`);
